package com.bank.flink.comp;

// Window assigner: floors the event time to a one-minute window start.
class WindowAssigner {
    private final long windowSizeMillis;

    WindowAssigner(long windowSizeMillis) {
        this.windowSizeMillis = windowSizeMillis;
    }

    long assign(RiskTxn txn) {
        long ts = txn.getEventTimeMillis();
        return ts - (ts % windowSizeMillis);
    }

    long windowEnd(long windowStart) {
        return windowStart + windowSizeMillis;
    }
}
