package com.bank.flink.comp;

// Trigger: returns FIRE every N elements (speculative) and the engine
// also fires once at window end. Mirrors TriggerResult.FIRE vs CONTINUE.
class CountTriggerPolicy {
    private final int everyN;

    CountTriggerPolicy(int everyN) {
        this.everyN = everyN;
    }

    // Called on each element; true means FIRE now (speculative).
    boolean onElement(int bufferedCount) {
        return bufferedCount % everyN == 0;
    }
}
