package com.bank.flink.comp;

import java.util.List;

// Evictor: keeps only the last N elements, removing the oldest ones
// BEFORE the window function (average) runs.
class LastNEvictor {
    private final int keepLast;

    LastNEvictor(int keepLast) {
        this.keepLast = keepLast;
    }

    // Returns the surviving sublist (the most recent keepLast elements).
    List<RiskTxn> evictBefore(List<RiskTxn> buffer) {
        if (buffer.size() <= keepLast) return buffer;
        return buffer.subList(buffer.size() - keepLast, buffer.size());
    }
}
