package com.bank.flink.comp;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Wires the three components together in Flink's order:
//   assign -> buffer -> trigger(FIRE?) -> evict -> window function.
class WindowComponentsEngine {
    private static final Logger log = Logger.getLogger(WindowComponentsEngine.class.getName());

    private final WindowAssigner assigner;
    private final CountTriggerPolicy trigger;
    private final LastNEvictor evictor;
    private final List<RiskTxn> buffer = new ArrayList<>();
    private long currentWindowStart = Long.MIN_VALUE;

    WindowComponentsEngine(WindowAssigner assigner, CountTriggerPolicy trigger, LastNEvictor evictor) {
        this.assigner = assigner;
        this.trigger = trigger;
        this.evictor = evictor;
    }

    void process(RiskTxn txn) {
        long windowStart = assigner.assign(txn);      // ASSIGNER
        if (currentWindowStart == Long.MIN_VALUE) currentWindowStart = windowStart;
        buffer.add(txn);                               // buffer element
        if (trigger.onElement(buffer.size())) {        // TRIGGER (speculative)
            fire("SPECULATIVE", windowStart);
        }
    }

    // Called by the engine when the window end is reached (final fire).
    void onWindowEnd() {
        fire("FINAL", currentWindowStart);
        buffer.clear(); // PURGE after final fire
    }

    private void fire(String kind, long windowStart) {
        List<RiskTxn> surviving = evictor.evictBefore(new ArrayList<>(buffer)); // EVICTOR
        BigDecimal sum = BigDecimal.ZERO;
        for (RiskTxn t : surviving) sum = sum.add(t.getAmount());
        BigDecimal avg = surviving.isEmpty() ? BigDecimal.ZERO
                : sum.divide(BigDecimal.valueOf(surviving.size()), 2, RoundingMode.HALF_UP);
        int kept = surviving.size();
        int total = buffer.size();
        log.info(() -> kind + " FIRE window=" + windowStart + " avg(last " + kept + " of "
                + total + ") = " + avg);
    }
}
