package com.bank.flink.comp;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: 12 transactions in one minute, speculative fires every 5,
// evictor keeps last 10, final fire at window end.
public class WindowComponentsDemo {
    private static final Logger log = Logger.getLogger(WindowComponentsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new CompLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WindowAssigner assigner = new WindowAssigner(60_000L);
        CountTriggerPolicy trigger = new CountTriggerPolicy(5);
        LastNEvictor evictor = new LastNEvictor(10);
        WindowComponentsEngine engine = new WindowComponentsEngine(assigner, trigger, evictor);

        // 12 Rajesh transactions all inside the 10:00 window (times 0..11s).
        for (int i = 0; i < 12; i++) {
            BigDecimal amount = new BigDecimal((i + 1) * 100);
            engine.process(new RiskTxn("SAV2001", amount, i * 1000L));
        }
        engine.onWindowEnd();
    }
}

// ─── Would be in CompLogFormatter.java in a real project ───
class CompLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
